const getRequestIdentity = `-- name: GetRequestIdentity :one
SELECT u.is_active, u.tokens_valid_from,
       COALESCE($1::uuid, u.active_org_id)::uuid AS org_id, m.role,
       EXISTS (SELECT 1 FROM revoked_sessions r WHERE r.token_hash = $2::text)::bool AS session_revoked
FROM users u
LEFT JOIN org_members m ON m.org_id = COALESCE($1::uuid, u.active_org_id) AND m.user_id = u.id
WHERE u.id = $3 LIMIT 1
`

type GetRequestIdentityParams struct {
	OrgID       pgtype.UUID `json:"org_id"`
	SessionHash *string     `json:"session_hash"`
	ID          pgtype.UUID `json:"id"`
}

type GetRequestIdentityRow struct {
	IsActive        bool               `json:"is_active"`
	TokensValidFrom pgtype.Timestamptz `json:"tokens_valid_from"`
	OrgID           pgtype.UUID        `json:"org_id"`
	Role            *string            `json:"role"`
	SessionRevoked  bool               `json:"session_revoked"`
}

// Everything the auth middleware needs per request in one round trip: the
// account's state, the moment before which its session tokens are refused,
// and its role in the workspace the request works in: org_id when the
// request names one (X-Toft-Org, D-52), else the one the account last
// switched to. The role is NULL when there is none or the user is not a
// member of it; the middleware then refuses a named workspace, and falls
// back to the earliest membership otherwise (org.Service.GetForUser).
// session_revoked: the session token with this sha256 was signed out.
func (q *Queries) GetRequestIdentity(ctx context.Context, arg GetRequestIdentityParams) (GetRequestIdentityRow, error) {
	row := q.db.QueryRow(ctx, getRequestIdentity, arg.OrgID, arg.SessionHash, arg.ID)
	var i GetRequestIdentityRow
	err := row.Scan(
		&i.IsActive,
		&i.TokensValidFrom,
		&i.OrgID,
		&i.Role,
		&i.SessionRevoked,
	)
	return i, err
}

