const updateServiceRuntimeStatus = `-- name: UpdateServiceRuntimeStatus :exec
WITH changed AS (
    SELECT s.server_id FROM services s
    WHERE s.id = $1
      AND (s.runtime_status IS DISTINCT FROM $2::text
           OR s.active_deployment_id IS DISTINCT FROM $3::uuid)
), updated AS (
    UPDATE services s
    SET runtime_status = $2, active_deployment_id = $3, updated_at = NOW()
    WHERE s.id = $1
)
UPDATE servers v SET spec_generation = v.spec_generation + 1 WHERE v.id IN (SELECT server_id FROM changed)
`

