const workspaceAliasUser = `-- name: WorkspaceAliasUser :many
SELECT s.name
FROM services s
LEFT JOIN environments e ON e.id = s.environment_id
LEFT JOIN projects p ON p.id = COALESCE(s.project_id, e.project_id)
WHERE s.network_alias = $1 AND s.id <> $2
  AND (s.scoped_org_id = $3 OR p.org_id = $3)
LIMIT 1
`

type WorkspaceAliasUserParams struct {
	Alias *string     `json:"alias"`
	ID    pgtype.UUID `json:"id"`
	OrgID pgtype.UUID `json:"org_id"`
}

// Another of the workspace's services with this network alias, in any
// scope: a workspace service joins every network of the workspace, so a
// moved one must not share an alias with any (D-162).
func (q *Queries) WorkspaceAliasUser(ctx context.Context, arg WorkspaceAliasUserParams) ([]string, error) {
	rows, err := q.db.Query(ctx, workspaceAliasUser, arg.Alias, arg.ID, arg.OrgID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []string{}
	for rows.Next() {
		var name string
		if err := rows.Scan(&name); err != nil {
			return nil, err
		}
		items = append(items, name)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
